  // `type` after the spread: a caller's `type` would otherwise send two keydowns.
  const key = async (opts = {}) => {
    for (const type of ["keyDown", "keyUp"]) await send("Input.dispatchKeyEvent", { ...opts, type });
  };

  const typeText = async (text) => {
    for (const char of text) await key({ text: char, key: char });
  };

  const pressEscape = () =>
    key({ key: "Escape", code: "Escape", windowsVirtualKeyCode: 27, nativeVirtualKeyCode: 27 });

  // Keeps the renderer unthrottled and focused even when Obsidian is not frontmost.
  const activate = async () => {
    await send("Page.setWebLifecycleState", { state: "active" }).catch(() => {});
    await send("Emulation.setFocusEmulationEnabled", { enabled: true }).catch(() => {});
  };

  const screenshot = async () =>
    Buffer.from((await send("Page.captureScreenshot", { format: "png" })).data, "base64");

  // Id and folder differ (@discourse-graph/obsidian vs discourse-graphs); resolve via manifests.
  const resolvePluginId = ({ pluginId, pluginFolder }) =>
    evaluate(`
      const ms = Object.values(app.plugins.manifests);
      const m = ms.find((m) => m.id === ${json(pluginId)}) ??
        ms.find((m) => (m.dir ?? "").split("/").pop() === ${json(pluginFolder)});
      return m ? m.id : null;
    `);

  const reloadPlugin = async (plugin) => {
    const id = await resolvePluginId(plugin);
    if (!id) throw new Error(`Plugin ${plugin.pluginId} / ${plugin.pluginFolder} not in manifests`);
    await evaluate(`
      return app.plugins.disablePlugin(${json(id)})
        .then(() => app.plugins.enablePlugin(${json(id)}))
        .then(() => true);
    `);
    await waitFor(`!!app.plugins.plugins[${json(id)}]?._loaded`, {
      label: `plugin ${id} loaded`,
      timeout: 15000,
    });
    return id;
  };

  // Escape first (modal cleanup code runs); force-remove survivors that ignore Escape.
  const clearModals = async () => {
    for (let i = 0; i < 3; i++) {
      if (await evaluate(`!document.querySelector(".modal-container")`)) return;
      await pressEscape();
      await waitFor(`!document.querySelector(".modal-container")`, { timeout: 300 }).catch(() => {});
    }
    await evaluate(`document.querySelectorAll(".modal-container").forEach((el) => el.remove()); return true;`);
  };

  return {
    send,
    evaluate,
    waitFor,
    key,
    typeText,
    pressEscape,
    activate,
    screenshot,
    resolvePluginId,
    reloadPlugin,
  const writeNote = (name, body) =>
    client.evaluate(`
      return (async () => {
        const p = ${json(verifyPath(name))};
        for (const dir of [${json("_verify")}, ${json(verifyDir)}])
          if (!app.vault.getAbstractFileByPath(dir)) await app.vault.createFolder(dir);
        const f = app.vault.getAbstractFileByPath(p);
        if (f) await app.vault.modify(f, ${json(body)});
        else await app.vault.create(p, ${json(body)});
        return p;
      })();
    `);
  return { client, vault, branch, json, verifyDir, verifyPath, writeNote };
};

export const runVerification = async ({ client, vault, branch, scenarios, artifactsDir, meta = {} }) => {
  mkdirSync(artifactsDir, { recursive: true });
  const ctx = makeContext({ client, vault, branch });
  const baselineLayout = await client.evaluate(`return app.workspace.getLayout();`);
  const shaBefore = bundleHash(vault.pluginDir);
  const results = [];

  const resetToBaseline = async () => {
    await client.clearModals();
    await client.evaluate(`return app.workspace.changeLayout(${json(baselineLayout)}).then(() => true);`);
  };

  try {
    for (const [i, scenario] of scenarios.entries()) {
      const started = Date.now();
      const row = { scenario: scenario.name, input: scenario.input ?? "", expected: scenario.expected ?? "" };
      let state;
      try {
        await resetToBaseline();
        state = scenario.setup ? await scenario.setup(ctx) : undefined;
        const actual = await scenario.run(ctx, state);
        const shot = path.join(artifactsDir, `${i + 1}-${slugify(scenario.name)}.png`);
        writeFileSync(shot, await client.screenshot());
        row.screenshot = shot;
        const verdict = await scenario.expect(actual, state);
        row.pass = typeof verdict === "object" ? !!verdict.pass : !!verdict;
        row.actual = toText(typeof verdict === "object" && "actual" in verdict ? verdict.actual : actual);
      } catch (error) {
        row.pass = false;
        row.actual = `ERROR: ${error.message.split("\n")[0]}`;
      } finally {
        if (scenario.teardown)
          await Promise.resolve(scenario.teardown(ctx, state)).catch((e) => console.error(`teardown failed: ${e.message}`));
      }
      row.ms = Date.now() - started;
      results.push(row);
      console.log(`${row.pass ? "PASS" : "FAIL"}  ${row.scenario} (${row.ms}ms) ${row.pass ? "" : row.actual}`);
    }
  } finally {
    await resetToBaseline().catch(() => {});
  }

  const bundleChanged = bundleHash(vault.pluginDir) !== shaBefore;
  if (bundleChanged) console.error("INVALID RUN: main.js changed mid-run (another watcher?)");
  const lastRun = {
    ...meta,
    branch,
    vault: vault.root,
    slot: vault.slot,
    verifyDir: ctx.verifyDir,
    bundleChangedDuringRun: bundleChanged,
    pass: !bundleChanged && results.every((r) => r.pass),
    results,
  };
  const lastRunPath = path.join(artifactsDir, "last-run.json");
  writeFileSync(lastRunPath, JSON.stringify(lastRun, null, 2));
  return { lastRun, lastRunPath };
};

